```rust
// Writing to master and immediately reading from asynchronous replica
async fn update_profile(client: &DbClient, profile: Profile) {
    // Write request routed to Primary database node
    client.write_primary(&profile).await.unwrap();

    // BUG: Replication lag! Read request is immediately routed to replica.
    // The replica hasn't caught up, so the user sees their old profile data.
    let fetched = client.read_replica(profile.user_id).await.unwrap();
}
